cd /tmp && cat > node-501-probe2.mjs <<'EOF'
import http from 'http';
import pkg from '/var/tmp/loop-bench/runs/13ef0bde5367/workspace/target/node_modules/ws/index.js';
const {WebSocket} = pkg;

const probe = (label, attach) => new Promise(resolve => {
  const s = http.createServer(() => {});
  attach(s);
  s.listen(0, () => {
    const {port} = s.address();
    const c = new WebSocket(`ws://127.0.0.1:${port}/x`);
    const done = what => { console.log(label, '->', what); c.terminate(); s.close(); resolve(); };
    c.on('error', e => done(`error: ${e.message}`));
    c.on('unexpected-response', (_req, res) => done(`unexpected-response: ${res.statusCode}`));
    setTimeout(() => done('TIMEOUT no error within 3s'), 3000);
  });
});

await probe('no-upgrade-listener', () => {});
await probe('silent-upgrade-listener', s => s.on('upgrade', () => {}));
EOF
timeout 30 node node-501-probe2.mjs
